"use client";
import React, { useState, useTransition } from "react";
import { executeMasterAction } from "@/app/actions/master-actions";

export default function MasterTemplatePage() {
  const [moduleName, setModuleName] = useState("Core-Module-Audit");
  const [provider, setProvider] = useState("google");
  const [inputData, setInputData] = useState("");
  const [auditResult, setAuditResult] = useState<any>(null);
  const [isPending, startTransition] = useTransition();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputData.trim()) return;

    startTransition(async () => {
      try {
        const res = await executeMasterAction(moduleName, provider, inputData);
        if (res.success) {
          setAuditResult(res.data);
        }
      } catch (error) {
        console.error("Error en la ejecución:", error);
      }
    });
  };

  return (
    <div className="min-h-screen bg-[#030712] text-slate-100 p-3 font-sans flex flex-col items-center">
      <div className="w-full max-w-xl mx-auto space-y-2.5 mt-1">
        <header className="flex justify-between items-center border border-slate-800 bg-slate-900 px-3 py-1.5 rounded-lg shadow">
          <div className="flex items-center gap-2">
            <div className="w-7 h-7 bg-cyan-600 rounded flex items-center justify-center font-bold text-xs text-white shadow">NX</div>
            <h1 className="text-xs font-bold text-white tracking-wide">Nexcode Master Core</h1>
          </div>
          <span className="text-[9px] text-emerald-400 font-mono">fg782270@gmail.com</span>
        </header>
        <main className="bg-slate-900 border border-slate-800 rounded-lg p-3 shadow-xl">
          <h2 className="text-[11px] font-semibold mb-2 text-cyan-400 uppercase font-mono tracking-wider flex items-center justify-between">
            <span>Panel de Gobernanza y Auditoría IA</span>
            <span className="text-[9px] text-slate-500">Macaly Cloud Gateway</span>
          </h2>
          <form onSubmit={handleSubmit} className="space-y-2.5">
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="block text-[9px] text-slate-400 font-mono mb-0.5">Módulo de Operación:</label>
                <input type="text" value={moduleName} onChange={(e) => setModuleName(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded p-1.5 text-xs text-slate-200 focus:outline-none focus:border-cyan-500" required />
              </div>
              <div>
                <label className="block text-[9px] text-slate-400 font-mono mb-0.5">Motor de IA:</label>
                <select value={provider} onChange={(e) => setProvider(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded p-1.5 text-xs text-slate-200 focus:outline-none focus:border-cyan-500">
                  <option value="google">Google Gemini</option>
                  <option value="openai">OpenAI GPT-4</option>
                  <option value="anthropic">Anthropic Claude</option>
                </select>
              </div>
            </div>
            <div>
              <label className="block text-[9px] text-slate-400 font-mono mb-0.5">Instrucción o Parámetro Institucional:</label>
              <textarea value={inputData} onChange={(e) => setInputData(e.target.value)} placeholder="Escribe la consulta para sellado de auditoría..." className="w-full h-16 bg-slate-950 border border-slate-800 rounded p-1.5 text-xs text-slate-200 focus:outline-none focus:border-cyan-500 resize-none" required />
            </div>
            <div className="flex justify-end">
              <button type="submit" disabled={isPending} className="px-3 py-1.5 bg-cyan-600 hover:bg-cyan-500 disabled:opacity-50 text-white font-semibold rounded text-xs shadow transition">
                {isPending ? "Procesando y Sellando..." : "Ejecutar y Sellar con SHA-256"}
              </button>
            </div>
          </form>
          {auditResult && (
            <div className="mt-2.5 space-y-1.5 border-t border-slate-800 pt-2 text-[11px] animate-fadeIn">
              <div className="p-2 bg-slate-950 rounded border border-emerald-900/50 text-emerald-300">
                <strong className="text-slate-400 uppercase text-[9px] block">Respuesta del Gateway:</strong> {auditResult.ai_response}
              </div>
              <div className="p-2 bg-slate-950 rounded border border-cyan-900/60 font-mono text-[9px] text-cyan-300 break-all">
                <strong className="text-slate-400 uppercase text-[8px] block">Hash SHA-256 Inmutable:</strong> {auditResult.blockchain_hash}
                <span className="block text-slate-500 mt-1 text-[8px]">Supervisor Autorizado: {auditResult.supervised_by}</span>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}